CREATE TABLE IF NOT EXISTS "PostAssemblyQaRun" ("id" TEXT NOT NULL PRIMARY KEY, "projectId" TEXT NOT NULL, "finalVideoPath" TEXT NOT NULL, "finalVideoHash" TEXT NOT NULL, "finalVideoVersion" TEXT NOT NULL, "validatorVersion" TEXT NOT NULL, "status" TEXT NOT NULL, "qualityStatusBefore" TEXT NOT NULL, "qualityStatusAfter" TEXT, "validatorsRun" JSONB NOT NULL, "findings" JSONB NOT NULL, "incidentsCreated" JSONB NOT NULL, "repairsTriggered" JSONB NOT NULL, "error" TEXT, "startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" DATETIME, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "PostAssemblyQaRun_projectId_finalVideoHash_validatorVersion_key" ON "PostAssemblyQaRun"("projectId", "finalVideoHash", "validatorVersion");
CREATE INDEX IF NOT EXISTS "PostAssemblyQaRun_projectId_updatedAt_idx" ON "PostAssemblyQaRun"("projectId", "updatedAt");
